from typing import List

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        total = len(nums1) + len(nums2)
        need = total // 2
        i = j = 0
        prev = curr = 0
        for _ in range(need + 1):
            prev = curr
            if j == len(nums2) or (i < len(nums1) and nums1[i] <= nums2[j]):
                curr = nums1[i]
                i += 1
            else:
                curr = nums2[j]
                j += 1
        if total % 2:
            return float(curr)
        return (prev + curr) / 2

